with lines as (select id, customer_id, coupon_codes, k, value from carts lateral view explode(attributes) x as k, value) select customer_id, k, count(*) filter (where k = 'utm_source') as utm_source_rows, size(collect_set(k)) as num_ks, sort_array(collect_set(k)) as k_list, sort_array(collect_set(k)) as k_list_2, size(collect_set(k)) as num_ks_2, sort_array(collect_set(k)) as k_list_3 from lines group by customer_id, k order by num_ks_2 desc nulls last;
